Here's how to write modern MSTest tests for your `DataFetcher` using async patterns, timeouts, and cancellation handling:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _sut;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        var client = new HttpClient(_handler) { BaseAddress = new Uri("https://example.com") };
        _sut = new DataFetcher(client);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_SuccessResponse_ReturnsContent()
    {
        // Arrange
        _handler.ResponseContent = "hello world";
        _handler.StatusCode = HttpStatusCode.OK;

        // Act
        var result = await _sut.FetchAsync("https://example.com/data",
            _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_NotFound_ThrowsHttpRequestException()
    {
        // Arrange
        _handler.StatusCode = HttpStatusCode.NotFound;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _sut.FetchAsync("https://example.com/missing",
                _testContext.CancellationToken));
    }

    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        // Arrange
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // pre-cancel

        // Act & Assert
        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _sut.FetchAsync("https://example.com/data", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_CancellationDuringRequest_ThrowsOperationCanceled()
    {
        // Arrange
        using var cts = new CancellationTokenSource();
        _handler.OnSendAsync = () => cts.Cancel(); // cancel mid-flight

        // Act & Assert
        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _sut.FetchAsync("https://example.com/slow", cts.Token));
    }

    // Minimal test double for HttpMessageHandler
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        public HttpStatusCode StatusCode { get; set; } = HttpStatusCode.OK;
        public string ResponseContent { get; set; } = string.Empty;
        public Action? OnSendAsync { get; set; }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            OnSendAsync?.Invoke();
            cancellationToken.ThrowIfCancellationRequested();

            return Task.FromResult(new HttpResponseMessage(StatusCode)
            {
                Content = new StringContent(ResponseContent)
            });
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---------|-----|
| **Async tests** | Return `async Task`, use `await` directly |
| **Timeouts** | `[Timeout(ms)]` attribute on each method |
| **Cooperative cancellation** | Flow `_testContext.CancellationToken` so the timeout actually aborts the test |
| **Cancellation testing** | Pre-cancel a `CancellationTokenSource` or cancel mid-request |
| **Exception assertions** | `Assert.ThrowsExactlyAsync<T>` instead of `[ExpectedException]` |
| **HttpClient testing** | Custom `HttpMessageHandler` — no mocking library needed |
| **Constructor init** | Enables `readonly` fields; inject `TestContext` via constructor (MSTest 3.6+) |

The critical detail: always pass `_testContext.CancellationToken` (or your own token) into the method under test so that `[Timeout]` can actually terminate a hung call cooperatively.
